MAP
  NAME "countries"
  CONFIG "MS_ERRORFILE" "stderr"
  DEBUG 5
  STATUS ON
  EXTENT -180 -90 180 90
  SIZE 800 400
  IMAGETYPE PNG
  FONTSET "/etc/mapserver/fonts.txt"
  WEB
    METADATA
      "ows_title"                   "Countries"
      "ows_enable_request"          "*"
      "ows_srs"                     "EPSG:4326 EPSG:3857"
      "ows_onlineresource"          "http://localhost:8080/countries"
      "oga_onlineresource"          "http://localhost:8080/countries/ogcapi"
      "oga_enable_request"          "*"
      "oga_title"                   "Countries"
      "oga_description"             "Simple countries dataset"
      "wms_rootlayer_name" ""
    END
  END
  PROJECTION
    "init=epsg:4326"
  END

  LAYER
    NAME "countries"
    TYPE POLYGON
    STATUS ON

    CONNECTIONTYPE OGR
    CONNECTION "ne_110m_admin.json"

    PROJECTION
      "init=epsg:4326"
    END

    CLASS
      LABEL
        TEXT " [ADMIN] "
        TYPE TRUETYPE
        FONT "arial"
        SIZE 6
        COLOR 255 255 255
        POSITION CC
        STYLE
          GEOMTRANSFORM "labelpoly"
          COLOR 200 23 21
          OUTLINECOLOR 2 2 2
          WIDTH 1
        END
      END
      STYLE
        COLOR 220 220 220
        OUTLINECOLOR 100 100 100
      END
    END

    METADATA
      "oga_title" "Countries"
      "oga_description" "Country boundaries"
      "oga_feature_collection" "true"
      "ows_srs" "EPSG:4326 EPSG:3857"
      "gml_include_items" "all"
      "gml_featureid" "ABBREV"
    END
    TEMPLATE "VOID"
  END
END